using nlohmann::json;
void to_json(json& j, const Node& n) {
  j = json{{"name", n.name}, {"children", n.children}};
}
void from_json(const json& j, Node& n) {
  n.name = j.at("name");
  n.children = j.value("children", std::vector<Node>{});
}
